 this.shadow(s.cage.home,425,130,23);this.house(s.cage.home,s.cage.nest,s.cage.stash);this.wheel(s.cage.wheel,t,s.pet.state==='wheel'&&Math.abs(s.pet.x-s.cage.wheel)<10);
