 if(s.play.remaining>0){const bx=s.play.x,by=423;this.shadow(bx,440,19,5);const ball=c.createRadialGradient(bx-5,by-6,1,bx,by,16);ball.addColorStop(0,'#dfb47a');ball.addColorStop(1,'#a16d43');c.fillStyle=ball;c.beginPath();c.arc(bx,by,15,0,Math.PI*2);c.fill();c.strokeStyle='#f2d4a0';c.lineWidth=2;c.beginPath();c.ellipse(bx,by,6,14,Math.sin(t*.002)*.3,0,7);c.stroke();c.fillStyle='#6f7e5e';c.font='13px system-ui';c.textAlign='center';c.fillText('Коснитесь подстилки, чтобы передвинуть мячик',500,28);c.textAlign='left';}
 const p=s.pet;if(this.visualX===null)this.visualX=p.x;this.visualX+=(p.x-this.visualX)*.11;
